#!/usr/bin/env python3

import sys
import json
import time
import urllib.request
import urllib.error

API_URL = "http://127.0.0.1:4000/v1/chat/completions"
TEST_PROMPT = "Reply with exactly one word: OK"
TIMEOUT_SECONDS = 30


def usage():
    print("Usage: python test_models.py <config.json>")
    sys.exit(1)


def load_models(path):
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    items = None

    if isinstance(data, list):
        items = data
    elif isinstance(data, dict):
        for key in ("models", "data"):
            if isinstance(data.get(key), list):
                items = data[key]
                break

    if items is None:
        raise ValueError(
            "Unsupported JSON format. Expected either:\n"
            "  - a list of model names\n"
            "  - {'models': [...]} or {'data': [...]}"
        )

    models = []
    for item in items:
        if isinstance(item, str):
            models.append(item)
        elif isinstance(item, dict):
            for key in ("id", "model", "name"):
                value = item.get(key)
                if isinstance(value, str) and value.strip():
                    models.append(value)
                    break

    if not models:
        raise ValueError("No models found in config file.")

    return models


def post_chat_completion(payload):
    body = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        API_URL,
        data=body,
        headers={"Content-Type": "application/json"},
        method="POST",
    )

    start = time.time()
    try:
        with urllib.request.urlopen(req, timeout=TIMEOUT_SECONDS) as resp:
            raw = resp.read().decode("utf-8", errors="replace")
            latency = time.time() - start
            return True, raw, latency
    except urllib.error.HTTPError as e:
        raw = e.read().decode("utf-8", errors="replace")
        latency = time.time() - start
        return False, raw, latency
    except Exception as e:
        latency = time.time() - start
        return False, str(e), latency


def extract_error_text(raw):
    try:
        obj = json.loads(raw)
        if isinstance(obj, dict):
            err = obj.get("error")
            if isinstance(err, dict):
                msg = err.get("message")
                if isinstance(msg, str) and msg.strip():
                    return msg
    except Exception:
        pass
    return raw


def response_indicates_temperature_not_supported(raw):
    text = extract_error_text(raw).lower()
    if "temperature" not in text:
        return False

    hints = [
        "not supported",
        "unsupported",
        "unknown",
        "invalid",
        "extra inputs are not permitted",
        "unexpected",
        "not allowed",
    ]
    return any(hint in text for hint in hints) or True


def extract_response_text(raw):
    try:
        obj = json.loads(raw)
    except Exception:
        return raw

    try:
        choices = obj.get("choices", [])
        if not choices:
            return json.dumps(obj, ensure_ascii=False)

        message = choices[0].get("message", {})
        content = message.get("content", "")

        if isinstance(content, str):
            return content

        if isinstance(content, list):
            parts = []
            for part in content:
                if isinstance(part, dict) and part.get("type") == "text":
                    parts.append(part.get("text", ""))
            return "".join(parts)

        return str(content)
    except Exception:
        return json.dumps(obj, ensure_ascii=False)


def preview_text(text, limit=50):
    text = text.replace("\r", " ").replace("\n", " ").strip()
    return text[:limit]


def test_model(model_name):
    total_start = time.time()

    payload = {
        "model": model_name,
        "messages": [{"role": "user", "content": TEST_PROMPT}],
        "max_tokens": 20,
        "temperature": 0,
    }

    ok, raw, _ = post_chat_completion(payload)

    if not ok and response_indicates_temperature_not_supported(raw):
        payload.pop("temperature", None)
        ok, raw, _ = post_chat_completion(payload)

    total_latency = time.time() - total_start

    if not ok:
        error_text = extract_error_text(raw)
        return {
            "model": model_name,
            "status": "FAIL",
            "latency": total_latency,
            "response": preview_text(error_text),
            "passed": False,
        }

    response_text = extract_response_text(raw)
    passed = response_text.strip() == "OK"

    return {
        "model": model_name,
        "status": "PASS" if passed else "FAIL",
        "latency": total_latency,
        "response": preview_text(response_text),
        "passed": passed,
    }


def print_table(results):
    rows = []
    for r in results:
        rows.append({
            "Model": r["model"],
            "Status": r["status"],
            "Latency": "{:.2f}s".format(r["latency"]),
            "Response": r["response"],
        })

    model_w = max(len("Model"), max(len(row["Model"]) for row in rows))
    status_w = max(len("Status"), max(len(row["Status"]) for row in rows))
    latency_w = max(len("Latency"), max(len(row["Latency"]) for row in rows))
    response_w = max(len("Response"), max(len(row["Response"]) for row in rows))

    header = (
        f"{'Model':<{model_w}}  "
        f"{'Status':<{status_w}}  "
        f"{'Latency':<{latency_w}}  "
        f"{'Response':<{response_w}}"
    )
    divider = (
        f"{'-' * model_w}  "
        f"{'-' * status_w}  "
        f"{'-' * latency_w}  "
        f"{'-' * response_w}"
    )

    print(header)
    print(divider)

    for row in rows:
        print(
            f"{row['Model']:<{model_w}}  "
            f"{row['Status']:<{status_w}}  "
            f"{row['Latency']:<{latency_w}}  "
            f"{row['Response']:<{response_w}}"
        )


def main():
    if len(sys.argv) != 2:
        usage()

    config_path = sys.argv[1]

    try:
        models = load_models(config_path)
    except Exception as e:
        print("Error loading models:", e)
        sys.exit(1)

    results = []
    for model in models:
        results.append(test_model(model))

    print_table(results)

    total = len(results)
    working = sum(1 for r in results if r["passed"])
    failed = total - working

    print()
    print(f"Total: {total} models | ✅ {working} working | ❌ {failed} failed")


if __name__ == "__main__":
    main()
